.cn-7tv-panel input{padding:7px 10px;border:1px solid #394255;border-radius:8px;background:#2e3749;color:#fff;font:13px system-ui;outline:none}
.cn-7tv-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(44px,1fr));gap:4px;overflow-y:auto;color:#a2b8d3;font:12px system-ui}
.cn-7tv-grid button{display:grid;place-items:center;height:44px;padding:2px;border:0;border-radius:8px;background:none;cursor:pointer}
.cn-7tv-grid button:hover{background:#ffffff14}
.cn-7tv-grid img{max-width:40px;max-height:36px}
.cn-7tv-suggest{position:fixed;z-index:9999;max-height:330px;overflow-y:auto;padding:4px;border:1px solid #394255;border-radius:10px;background:#1f2737;box-shadow:0 10px 30px #0008;font:13px system-ui;color:#e7eef8;scrollbar-width:thin}
.cn-7tv-suggest-head{padding:4px 8px 6px;color:#8b97ac;font-size:10px}
.cn-7tv-option{display:grid;grid-template-columns:36px minmax(0,1fr);align-items:center;gap:8px;padding:4px 8px;border-radius:6px;cursor:pointer}
.cn-7tv-option img{max-width:36px;max-height:28px;justify-self:center}
.cn-7tv-option span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cn-7tv-active{background:#29b6f62e;box-shadow:inset 3px 0 0 #29b6f6}`;
